<script setup lang="ts">
import {computed} from 'vue';
import FaultPicker from './FaultPicker.vue';
export interface Stage {name:string;end_hour:number;grid_ratio:number;emergency_ratio:number;failed_lines:number[]}
const stages=defineModel<Stage[]>({required:true});const props=defineProps<{disabled:boolean;network:boolean;lines?:any[];hours?:number}>();
const warning=computed(()=>{if(!stages.value.length)return '';let previous=0;const names=new Set<string>();for(const stage of stages.value){if(!stage.name.trim()||names.has(stage.name.trim()))return '阶段名称须非空且不重复';names.add(stage.name.trim());if(!Number.isInteger(stage.end_hour)||stage.end_hour<=previous)return '阶段结束小时须为严格递增的整数';previous=stage.end_hour}return props.hours!=null&&previous!==props.hours?`最后阶段结束小时为${previous}，当前输入${props.hours}小时，请调整覆盖范围。`:''});
function add(){let number=1;while(stages.value.some(s=>s.name.trim()==='阶段'+number))number++;stages.value=[...stages.value,{name:'阶段'+number,end_hour:(stages.value[stages.value.length-1]?.end_hour||0)+12,grid_ratio:1,emergency_ratio:1,failed_lines:[]}]}
function failures(s:Stage,e:Event){const v=(e.target as HTMLInputElement).value;s.failed_lines=v.trim()?v.split(/[,，]/).map(Number):[]}
</script>
<template><article><h3>运行阶段与故障恢复</h3><p>结束小时以首条数据为0点，按左闭右开区间划分。阶段名称须非空且不重复，结束小时须严格递增，最后结束小时必须等于数据条数。空表表示全时域统一参数；启用阶段后，阶段故障替代全局故障设置，储能能量连续传递。</p><p>当前输入：{{hours??'未提供'}}小时</p><p v-if="warning" class="error">{{warning}}</p><button v-if="stages.length&&hours" :disabled="disabled||hours<=(stages[stages.length-2]?.end_hour||0)" @click="stages[stages.length-1].end_hour=hours!">将末阶段对齐输入末尾</button><div class="scroll"><table><tr><th>阶段名称</th><th>结束小时</th><th>电网可用比例</th><th>应急电源可用比例</th><th v-if="network">故障支路</th><th>操作</th></tr><tr v-for="(s,i) in stages" :key="i"><td><input v-model="s.name" :disabled="disabled"></td><td><input v-model.number="s.end_hour" type="number" min="1" :disabled="disabled"></td><td><input v-model.number="s.grid_ratio" type="number" min="0" max="1" step="0.1" :disabled="disabled"></td><td><input v-model.number="s.emergency_ratio" type="number" min="0" max="1" step="0.1" :disabled="disabled"></td><td v-if="network"><FaultPicker v-model="s.failed_lines" :lines="lines||[]" :disabled="disabled"/></td><td><button @click="stages.splice(i,1)" :disabled="disabled">移除</button></td></tr></table></div><button @click="add" :disabled="disabled||stages.length>=20">＋ 添加阶段</button></article></template>
<style scoped>input{width:120px;border:1px solid #c8dcdf;border-radius:4px;padding:8px}td:first-child input{width:160px}.scroll{margin-bottom:12px}</style>
